import { z } from 'zod';

export const generateRoadmapRequestSchema = z.object({
  force_regenerate: z.boolean().default(false),
  custom_goal_notes: z.string().trim().max(500).optional(),
});

export const uuidRegex = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

/**
 * Schema validating the structured JSON generated by Gemini.
 * Gemini must supply verifiable lesson slugs/ids and skill codes.
 */
export const geminiRoadmapItemSchema = z.object({
  item_type: z.enum(['lesson', 'quiz', 'practice_test', 'review_session', 'diagnostic']),
  lesson_id: z.string().regex(uuidRegex, 'Invalid UUID format').optional().nullable(),
  lesson_slug: z.string().optional().nullable(),
  skill_code: z.string().optional().nullable(),
  quiz_id: z.string().regex(uuidRegex, 'Invalid UUID format').optional().nullable(),
  title: z.string().min(3).max(150),
  description: z.string().max(500).optional(),
  estimated_duration_minutes: z.number().int().min(10).max(180),
  pedagogical_priority: z.enum(['critical_gap', 'reinforcement', 'mastery_challenge', 'review']).default('reinforcement'),
});

export const geminiRoadmapResponseSchema = z.object({
  roadmap_title: z.string().min(5).max(150),
  target_pathway: z.enum(['foundation', 'pre_sat', 'sat_advanced']),
  overview_strategy: z.string().min(10).max(1000),
  weeks_allocated: z.number().int().min(1).max(52),
  items: z.array(geminiRoadmapItemSchema).min(3).max(60),
});

export type GenerateRoadmapRequest = z.infer<typeof generateRoadmapRequestSchema>;
export type GeminiRoadmapItem = z.infer<typeof geminiRoadmapItemSchema>;
export type GeminiRoadmapResponse = z.infer<typeof geminiRoadmapResponseSchema>;
